mapper.select:
SELECT gp.* FROM gld_period gp, gld_set_of_books gsof, gld_financial_attribute gfa WHERE gfa.COMPANY_ID = #{companyId} AND gfa.SET_OF_BOOKS_ID = gsof.SET_OF_BOOKS_ID AND gsof.PERIOD_SET_ID = gp.PERIOD_SET_ID AND gp.PERIOD_NAME IN ( SELECT gps.PERIOD_NAME FROM gld_period_status gps WHERE gps. STATUS = 'OPEN' AND gps.company_id = #{companyId} )
AND gp.PERIOD_NAME = #{periodName}
ORDER BY PERIOD_NAME desc
